    fn parse_param_attributes(
        &mut self,
        attrs: &[syn::Attribute],
        ty: &metadata::Type,
    ) -> Result<metadata::ParamAttributes, Error> {
        let mut attributes = metadata::ParamAttributes::default();

        for attr in attrs {
